    doc_term_freqs = dict(tf_pairs)
    df_counts = Counter()
    for tf in doc_term_freqs.values():
        df_counts.update(tf.keys())
    vocabulary = set(df_counts)
    if len(doc_term_freqs) != len(tf_pairs):
        for _, tf in tf_pairs: vocabulary.update(tf.keys())
    index.vocabulary = vocabulary
    index.document_frequencies = {t: df_counts.get(t, 0) for t in vocabulary}
    N = num_documents
