        for t, w in vec.items():
            ns += w * w
            app[t]((doc_id, w))
        doc_vectors[doc_id] = vec; doc_norms[doc_id] = sqrt(ns)
    for pl in postings.values(): pl.sort(key=lambda x: x[1], reverse=True)
    index.inverted_index = postings
    return index
